import hashlib, json, struct

target = "e98d9238eb5b343ceb8661b78e939874148b90db64578db6e0412d48fa8d2a03"
Q,A = "a","b"

def sha(b): return hashlib.sha256(b).hexdigest()

def cbor_text(s):
    b=s.encode(); n=len(b)
    assert n<24
    return bytes([0x60+n])+b
def cbor_map(n): return bytes([0xA0+n])
def cbor_arr(n): return bytes([0x80+n])
def cbor_null(): return b"\xf6"
def cbor_bool(v): return b"\xf5" if v else b"\xf4"

def mp_str(s):
    b=s.encode(); n=len(b)
    assert n<32
    return bytes([0xA0+n])+b
def mp_map(n): return bytes([0x80+n])
def mp_arr(n): return bytes([0x90+n])

cands=[]
# CBOR shapes
def cb(shape):
    # shape: tuples describing
    pass
cbor_variants = [
    ("cbor {basic:{q,a}}", cbor_map(1)+cbor_text("basic")+cbor_map(2)+cbor_text("question")+cbor_text(Q)+cbor_text("answer")+cbor_text(A)),
    ("cbor {q,a}", cbor_map(2)+cbor_text("question")+cbor_text(Q)+cbor_text("answer")+cbor_text(A)),
    ("cbor [q,a]", cbor_arr(2)+cbor_text(Q)+cbor_text(A)),
    ("cbor [basic,q,a]", cbor_arr(3)+cbor_text("basic")+cbor_text(Q)+cbor_text(A)),
    ("cbor {basic:[q,a]}", cbor_map(1)+cbor_text("basic")+cbor_arr(2)+cbor_text(Q)+cbor_text(A)),
    ("cbor {q,a,family:null}", cbor_map(3)+cbor_text("question")+cbor_text(Q)+cbor_text("answer")+cbor_text(A)+cbor_text("family")+cbor_null()),
]
mp_variants = [
    ("mp {basic:{q,a}}", mp_map(1)+mp_str("basic")+mp_map(2)+mp_str("question")+mp_str(Q)+mp_str("answer")+mp_str(A)),
    ("mp {q,a}", mp_map(2)+mp_str("question")+mp_str(Q)+mp_str("answer")+mp_str(A)),
    ("mp [q,a]", mp_arr(2)+mp_str(Q)+mp_str(A)),
    ("mp [basic,q,a]", mp_arr(3)+mp_str("basic")+mp_str(Q)+mp_str(A)),
    ("mp {basic:[q,a]}", mp_map(1)+mp_str("basic")+mp_arr(2)+mp_str(Q)+mp_str(A)),
]
for label,b in cbor_variants+mp_variants:
    if sha(b)==target: print("MATCH:",label,b.hex())

# json with family null
for js in [(",",":"),(", ",": ")]:
    for obj in [
        {"question":Q,"answer":A,"family":None},
        {"basic":{"question":Q,"answer":A},"family":None},
        {"content":{"basic":{"question":Q,"answer":A}}},
        {"deckName":"Deck","content":{"basic":{"question":Q,"answer":A}}},
    ]:
        s=json.dumps(obj,separators=js)
        if sha(s.encode())==target: print("MATCH json:",s)

# utf-16
for s in ["ab","a\nb","a:b","a\0b",'{"basic":{"question":"a","answer":"b"}}']:
    for enc in ["utf-16-le","utf-16-be","utf-16"]:
        if sha(s.encode(enc))==target: print("MATCH utf16:",s,enc)

# merkle with tags
hq=hashlib.sha256(Q.encode()).digest(); ha=hashlib.sha256(A.encode()).digest()
for tag in [b"",b"basic",b"Basic",b"\x00",b"\x01"]:
    for combo in [tag+hq+ha, hq+ha+tag, tag+hq.hexdigest().encode()+ha.hexdigest().encode()]:
        if sha(combo)==target: print("MATCH merkle:",tag)
print("done")
EOF
