import json, struct, sys
sys.path.insert(0,'/workspace/spec')
from blake3 import blake3

def basic_card_hash(q,a): return blake3(('Basic'+q+a).encode()).hex()
def cloze_family_hash(t): return blake3(('Cloze'+t).encode()).hex()
def cloze_card_hash(t,s,e): return blake3(b'Cloze'+t.encode()+struct.pack('<QQ',s,e)).hex()

assert blake3(b'').hex()=='af1349b9f5f9a1a6a0404dea36dcc9499bcb25c9adc112b7cc9a93cae41f3262'
d=json.load(open('/tmp/export_example.json'))
ok=0
for c in d['cards']:
    ct=c['content']
    if 'basic' in ct:
        h,fam = basic_card_hash(ct['basic']['question'],ct['basic']['answer']), None
    else:
        z=ct['cloze']; h,fam = cloze_card_hash(z['text'],z['start'],z['end']), cloze_family_hash(z['text'])
    ok += (h==c['hash'] and fam==c['familyHash'])
print(f'{ok}/{len(d[\"cards\"])} example cards OK; blake3 self-test OK')
"
